import{z as d,x as p,o as t,c as B,q as n,j as s,D as e,d as l,s as i,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"谓词逻辑与量词","description":"","frontmatter":{"title":"谓词逻辑与量词","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/predicate-logic.md","filePath":"cs/predicate-logic.md","lastUpdated":1791413859000}'),A={name:"cs/predicate-logic.md"};function h(m,a,f,u,c,x){const o=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=n('<h1 id="谓词逻辑与量词" tabindex="-1">谓词逻辑与量词 <a class="header-anchor" href="#谓词逻辑与量词" aria-label="Permalink to &quot;谓词逻辑与量词&quot;">​</a></h1><div class="epigraph"><p>一阶逻辑把原子换成关系与函数，加上 $\\forall,\\exists$。有效式可半判定，不可判定；有限模型上又回到 SAT 的亲戚。</p><footer>—— 据 Enderton；Church, 1936；Turing, 1936 整理</footer></div><p>上一课<a href="/cs/propositional-logic-cnf">命题与范式</a> 的赋值是有限 \\(2^n\\)。缺口是<strong>一阶</strong>：论域可无限，量词绑定变元。程序规范「对所有输入」落在这里。本课钉语法、结构、满足，以及 Church 不可判定；自然演绎下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言：函数符、谓词符、等号。项、原子、公式。结构 \\(\\mathfrak{M}\\)：论域 \\(|\\mathfrak{M}|\\)，解释符号。赋值把自由变元映到论域。\\(\\mathfrak{M}\\models\\varphi\\) 闭式为真。有效：一切结构为真。命题是一阶的无量词、无函数的碎片。<span class="marginnote">「论域」翻译成大白话：一份<strong>允许谈论的对象名单</strong>，比如「全体自然数」或「这间教室里的所有人」。「结构」则是名单加一张解释表——每个符号在名单上指谁、每个关系在名单上何时成立。所以 \\(\\forall\\) 只遍历名单上的人，名单换了，同一句话的真值可以整个翻掉。</span></p><p>有效性 RE 完全（完备性给半判定：能证则有效，且可枚举证明）。不可判定：把 TM 停机编成句子（Church–Turing）。有限模型上，一阶句子的有限可满足仍不可判定（Trakhtenbrot），点名。</p><h3 id="不是「英语的所有-存在」" tabindex="-1">不是「英语的所有 / 存在」 <a class="header-anchor" href="#不是「英语的所有-存在」" aria-label="Permalink to &quot;不是「英语的所有 / 存在」&quot;">​</a></h3><p>量词论域由结构指定，不是宇宙中的一切东西。换结构，同一句子真值可翻。绑定与 λ 课的捕获同一卫生问题。</p><p><span class="marginnote">Enderton 一阶章。Church 1936 判定问题。Gödel 完备性（下一课可靠完备的一阶版）。本课不进二阶逻辑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 \\(\\forall x\\exists y\\ R(x,y)\\) 在自然数后继与在有限图上的不同。Skolem：\\(\\forall x\\exists y\\) 换成函数 \\(f(x)\\)，等可满足。Prenex 点名。不要把 Prolog 当定义。<span class="marginnote">直觉类比：Skolem 化像客服中心的人事安排——「每位顾客都能找到一名接线员」\\((\\forall x\\exists y)\\) 落到执行层面就是设一张排班表 \\(f\\)，顾客 \\(x\\) 来了直接派 \\(f(x)\\)；不必存在统一的那名万能接线员。逻辑里把依赖前面全称变元的 \\(\\exists y\\) 换成一个新函数符，可满足性保持不变，量词就消掉了。</span></p>',11)),(t(),s(E,null,{default:e(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E5%91%BD%E9%A2%98%22%5D%20--%3E%20FOL%5B%22%E9%A1%B9%20%2B%20%E9%87%8F%E8%AF%8D%22%5D%0A%20%20FOL%20--%3E%20STR%5B%22%E7%BB%93%E6%9E%84%20%E2%8A%A8%22%5D%0A%20%20FOL%20--%3E%20UND%5B%22%E6%9C%89%E6%95%88%E6%80%A7%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[l("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"Hoare 逻辑的断言语言需要量词谈数组全体下标。SMT 把一阶碎片（算术、数组）交给判定器——可判定理论是特例，不是本课的完全一阶。本课先承认一般一阶太宽。",-1)),a[5]||(a[5]=r("p",null,"Herbrand：无等式时，可满足性与基项上的命题可满足相关，给 SMT 实例化埋伏。",-1)),a[6]||(a[6]=r("p",null,"自由变元必须在结构里赋值才有真值；闭式才谈 \\(\\mathfrak{M}\\models\\varphi\\)。空论域约定因系统而异，本课默认非空。二阶量词可谈「存在性质」，表达力骤升、证明论不同。Trakhtenbrot：有限可满足不可判定，故「只关心有限模型」帮不掉一般一阶。",-1)),a[7]||(a[7]=r("p",null,"量词顺序为什么致命——把两句话摆成对局就看清了：",-1)),(t(),s(E,null,{default:e(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E2%88%80x%20%E2%88%83y%20R(x%2Cy)%22%5D%20--%3E%20B%5B%22%E5%AF%B9%E6%89%8B%E4%BB%BB%E9%80%89%20x%EF%BC%8C%E4%BD%A0%E5%86%8D%E7%AD%94%20y%22%5D%0A%20%20B%20--%3E%20C%5B%22y%20%E5%8F%AF%E4%BB%A5%E8%A7%81%20x%20%E8%A1%8C%E4%BA%8B%EF%BC%9Ay%3Df(x)%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BD%A0%E6%9C%89%E5%BF%85%E8%83%9C%E7%AD%96%E7%95%A5%E5%88%99%E4%B8%BA%E7%9C%9F%22%5D%0A%20%20E%5B%22%E2%88%83y%20%E2%88%80x%20R(x%2Cy)%22%5D%20--%3E%20F%5B%22%E4%BD%A0%E5%85%88%E5%9B%BA%E5%AE%9A%E4%B8%80%E4%B8%AA%20y%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%AF%B9%E6%89%8B%E5%86%8D%E6%8C%91%20x%20%E4%B8%BA%E9%9A%BE%E4%BD%A0%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20y%20%E8%A6%81%E5%BA%94%E4%BB%98%E6%89%80%E6%9C%89%20x%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">数字实例能看出量词嵌套的代价：论域有 \\(n\\) 个元素时，检查一层 \\(\\forall\\) 要看 \\(n\\) 个值；\\(k\\) 层量词嵌套就是 \\(n^k\\) 个组合。\\(n=1000\\)、三层量词已是 \\(10^9\\) 次检查——这就是为什么把「程序对所有输入正确」写成一阶公式容易，而机器<strong>自动判定</strong>它真假却不可能（Church–Turing）：搜索空间随论域与量词层数爆炸到不可行。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证完备性，不写公理表。不引入集合论公理化。后课默认：规范写成一阶公式相对某结构；有效性不可判定。下一课证明系统：自然演绎。</p><p>有效性可半判定（枚举证明）但不可判定。程序规范里的「对所有输入」是一阶句子相对某结构，不是英语全称。SMT 后课只占领可判定碎片，不收回本课的否定结果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一阶：结构解释函数与关系；量词在论域上走。</li><li>有效可半判定、不可判定。</li><li>命题是无量词碎片；程序规范需要量词。</li><li>出处：Enderton；Church, 1936。</li></ul>',6))])}const T=d(A,[["render",h]]);export{C as __pageData,T as default};
